#include "Zancle/HasBuiltin.hpp"


#if ZA_HAS_BUILTIN(__is_trivially_assignable) && ZA_HAS_BUILTIN(__add_lvalue_reference)

////////////////////////////////////////////////////////////
// Headers
////////////////////////////////////////////////////////////
    #include "Zancle/Trait/AddConst.hpp"


    ////////////////////////////////////////////////////////////
    #define ZA_IS_TRIVIALLY_COPY_ASSIGNABLE(...) \
        __is_trivially_assignable(__add_lvalue_reference(__VA_ARGS__), __add_lvalue_reference(::za::AddConst<__VA_ARGS__>))

#else

////////////////////////////////////////////////////////////
// Headers
////////////////////////////////////////////////////////////
    #include <type_traits>


    ////////////////////////////////////////////////////////////
    #define ZA_IS_TRIVIALLY_COPY_ASSIGNABLE(...) ::std::is_trivially_copy_assignable_v<__VA_ARGS__>

#endif


namespace za
{
////////////////////////////////////////////////////////////
template <typename T>
inline constexpr bool isTriviallyCopyAssignable = ZA_IS_TRIVIALLY_COPY_ASSIGNABLE(T);

} // namespace za
